import sqlite3,math,heapq
c=sqlite3.connect('locations.db')
L={r[0]:(tuple(map(int,r[1].split(','))),r[2],[h for h in r[3].split(';') if h]) for r in c.execute('select * from locations')}
adj={}
for a,b in c.execute('select * from hub_links'): adj.setdefault(a,set()).add(b); adj.setdefault(b,set()).add(a)
def route(o,d):
    g={k:set(v) for k,v in adj.items()}
    for x in (o,d):
        if not L[x][1]:
            for h in L[x][2]: g.setdefault(x,set()).add(h); g.setdefault(h,set()).add(x)
    dist={o:0};prev={};pq=[(0,o)]
    while pq:
        du,u=heapq.heappop(pq)
        if u==d: break
        if du>dist[u]: continue
        if u!=o and not L[u][1]: continue
        for v in g.get(u,()):
            if not L[v][1] and v!=d: continue
            nd=du+math.dist(L[u][0],L[v][0])
            if nd<dist.get(v,1e18): dist[v]=nd;prev[v]=u;heapq.heappush(pq,(nd,v))
    p=[d]
    while p[-1]!=o: p.append(prev[p[-1]])
    p=p[::-1]
    legs=[(p[i],p[i+1],math.dist(L[p[i]][0],L[p[i+1]][0])) for i in range(len(p)-1)]
    return p,legs,dist[d]
for o,d in [('Guangzhou','Lima'),('Shanghai','Beijing')]:
    p,legs,D=route(o,d); print(p,[(a,b,round(x,1)) for a,b,x in legs],round(D,1),round(D*0.13,2))
    for a in p: print(' ',a,L[a][0])
import math
s=[n for n,v in L.items() if v[1] or v[2]]
print(sorted(s,key=lambda n: math.dist(L['Abu Dhabi'][0],L[n][0]))[:3], [round(math.dist(L['Abu Dhabi'][0],L[n][0]),1) for n in sorted(s,key=lambda n: math.dist(L['Abu Dhabi'][0],L[n][0]))[:3]])
print(L['San Jose'],L['San José'])
EOF

