lits = {}
for s in srcs:
    p = pathlib.Path(s)
    if not p.exists(): print("missing source", p.name); continue
    for line in p.read_text(errors="ignore").splitlines():
        m = re.match(r'\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$', line)
        vals = []
        if m:
            name, v = m.group(1), m.group(2).strip().strip('"').strip("'")
            vals = [(f"{p.name}:{name}", x) for x in (v.split(",") if name == "INVITE_CODES" else [v])]
        elif line.strip():
            vals = [(p.name, line.strip())]
        for n, v in vals:
            v = v.strip()
            if len(v) >= 6 and not v.startswith(("http://", "https://")): lits[v] = n
shapes = {"sk-": r'sk-[A-Za-z0-9_\-]{20,}', "github": r'\b(?:ghp|gho|ghs)_[A-Za-z0-9]{30,}', "AIza": r'AIza[0-9A-Za-z_\-]{35}',
          "privkey": r'-----BEGIN [A-Z ]*PRIVATE KEY', "bearer": r'[Bb]earer [A-Za-z0-9\-_.]{30,}', "cf-token": r'\b[A-Za-z0-9_-]{40}\b(?=.{0,40}(?:CF_|CLOUDFLARE))',
          "jwt": r'eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}'}
hits = {}; shape_hits = {}
files = [f for f in root.rglob("*") if f.is_file()]
for f in files:
    t = f.read_text(errors="ignore")
    for v, n in lits.items():
        c = t.count(v) + (t.count(json.dumps(v)[1:-1]) if json.dumps(v)[1:-1] != v else 0)
        if c: hits[n] = hits.get(n, 0) + c
    for k, pat in shapes.items():
        c = len(re.findall(pat, t))
        if c: shape_hits[k] = shape_hits.get(k, 0) + c
print("files", len(files), "literals", len(lits))
print("literal hits", hits or "none")
print("shape hits", shape_hits or "none")
